## File containing all custom functions used in analyzing human and mouse autopod data
## Alexander Okamoto
## January 13, 2026

#read in RSEM gene results counts and create a dataframe
#filepath should be a string with the full path to the RSEM results (ending with ".genes.results")
#samplenames should the unique names of the samples to be used from the folder specified in 'filepath'.

read_in_counts <- function(filepath, samplenames, min_reads = 1){
  #Put the sample data into a dataframe.
  countData.list <- sapply(samplenames, function(x) read.table(file=paste0(filepath, x, ".genes.results"), header=T, sep="\t"), simplify=F)
  countData.df <- do.call("cbind", countData.list)
  colsToKeep <- c(1, grep("expected_count", names(countData.df)))
  ct <- countData.df[,colsToKeep]
  names(ct) <- c("gene_id", samplenames)
  
  #We need to round the numbers since Deseq only likes integers, and right now all the counts have  decimal points
  #so this rounds each number. It should be 2:n, which n being the number of samples plus one. 
  ct[,2:ncol(ct)] <- round(ct[,2:ncol(ct)])
  
  #filter out rows with 1 or less reads
  ct <- ct[which(rowSums(ct[,2:ncol(ct)]) > min_reads),]
  
  #return the completed counts dataframe
  return(ct)
}

#initialize function
#design_in is the DESeq model input
#this version is specific to mouse

runDESEQ2_df <- function(design_in, count_data, col_data, padj.cutoff = 0.05){
  
  #glm design
  # Again, we can include more things beside tissue, like we could look at the effect of tissue *and* age, or we could control for sex here. 
  
  #build DESeqDataSet
  rsem.in <- DESeqDataSetFromMatrix(countData = count_data, colData = col_data, design = design_in, tidy = T)
  #pre-filter rows with 0 or 1 read
  rsem.in <- rsem.in[ rowSums(counts(rsem.in)) >= 1, ]
  rsem_cols <-as.data.frame(row.names(rsem.in))
  colnames(rsem_cols) <- 'ensembl_gene_id'
  rsem_annot <- merge(x= rsem_cols, y =  mouse_annot,
                      by= 'ensembl_gene_id', no.dups = TRUE, all.x=TRUE) %>% setorder(cols = "ensembl_gene_id")  
  #remove duplicate rows
  rsem_annot <- rsem_annot[!duplicated(rsem_annot$ensembl_gene_id),]
  mcols(rsem.in) <- cbind(mcols(rsem.in), rsem_annot$mgi_symbol)
  
  
  #fix gene names in rsem.in
  #don't have to do this--when deseq reads in gene names from rsem file it duplicates name of gene. Gets rid of second name. 
  #rownames(rsem.in) <-  sapply(strsplit(c(rownames(rsem.in)), split = '_', fixed = TRUE), function(x) (x[1]))
  
  #calculate DGE likelihood ratio test
  #LRT needs reduced. Just W t
  
  #, test = "LRT", reduced = reducedest--pairwise does not need it. Or post-hoc tests can compare between pairs. 
  rsem.de <- DESeq(rsem.in)
  
  #rsem.in variable is building the dataset 
  #now model is in rsem.de
  
  #summarized experiment input
  #can set alpha level at whatever
  rsem.de.res <- results(rsem.de, alpha = 0.05)
  #
  rsem.de.res$mgi_symbol <- mcols(rsem.in)['rsem_annot$mgi_symbol']
  
  #summary shows summary of results
  summary(rsem.de.res)
  
  #This is a way to export a table of the differentially expressed genes, ordered by p-value
  rsem.de.res.df <- rsem.de.res[order(rsem.de.res$padj),] %>% as.data.frame() %>% dplyr::filter(padj < padj.cutoff)
  
  return(rsem.de.res.df)
} #end function


#initialize function
#design_in is the DESeq model input
#this version is specific to mouse

runDESEQ2_df_no_annot <- function(design_in, count_data, col_data, padj.cutoff = 0.05){
  
  #glm design
  # Again, we can include more things beside tissue, like we could look at the effect of tissue *and* age, or we could control for sex here. 
  
  #build DESeqDataSet
  rsem.in <- DESeqDataSetFromMatrix(countData = count_data, colData = col_data, design = design_in, tidy = T)
  #pre-filter rows with 0 or 1 read
  rsem.in <- rsem.in[ rowSums(counts(rsem.in)) >= 1, ]
  rsem_cols <-as.data.frame(row.names(rsem.in))

  #fix gene names in rsem.in
  #don't have to do this--when deseq reads in gene names from rsem file it duplicates name of gene. Gets rid of second name. 
  #rownames(rsem.in) <-  sapply(strsplit(c(rownames(rsem.in)), split = '_', fixed = TRUE), function(x) (x[1]))
  
  #calculate DGE likelihood ratio test
  #LRT needs reduced. Just W t
  
  #, test = "LRT", reduced = reducedest--pairwise does not need it. Or post-hoc tests can compare between pairs. 
  rsem.de <- DESeq(rsem.in)
  
  #rsem.in variable is building the dataset 
  #now model is in rsem.de
  
  #summarized experiment input
  #can set alpha level at whatever
  rsem.de.res <- results(rsem.de, alpha = 0.05)
  #summary shows summary of results
  summary(rsem.de.res)
  
  #This is a way to export a table of the differentially expressed genes, ordered by p-value
  rsem.de.res.df <- rsem.de.res[order(rsem.de.res$padj),] %>% as.data.frame() %>% dplyr::filter(padj < padj.cutoff)
  
  return(rsem.de.res.df)
} #end function

