#design a function to count nearby peaks for a given gene
count_nearby_peaks <- 
  function(gene, padding = 200000, peakset){
  #gene should be the hgnc symbol of gene 
  #peakset should be the full file name of a target bed set
  
  #load packages
  require(tidyverse)
  
  #load refgene data
  refgene <- read_delim(file = "~/Desktop/Capellini_Lab/Capellini_Lab_Peak_Sets/Other_Peak_sets/hg38_refGene.txt", 
                        delim ='\t', 
                        col_names = F, 
                        show_col_types = FALSE) %>% 
    dplyr::select(c(X3, X5, X8, X13)) %>% unique() 
  colnames(refgene) <- c("chr", "start", "end", "hgnc_symbol")
  
  #cleaup if needed refgene <- refgene[!duplicated(refgene$hgnc_symbol),]
  #get specific info for gene
  gene_info <- refgene %>% dplyr::filter(hgnc_symbol == gene)
  
  if(nrow(gene_info)==0){
    return(NA)
  }
  else{
  gene_info$window_start <- gene_info$start - padding
  gene_info$window_end <- gene_info$end + padding
  
  
  #fix any negative start values 
  if(gene_info$window_start[1] < 1){
    gene_info$window_start[1] <- 1
  }
  
  peak_overlap_n <- system(paste("echo '", gene_info$chr[1], "\t", gene_info$window_start[1], "\t", gene_info$window_end[1],
               "' | bedtools intersect -a stdin -b ", peakset, " | wc -l", sep = ""), 
         intern = T) %>% 
    readr::parse_number()

  #return the number of peak sets
  return(peak_overlap_n)
  }
} #end count_nearby_peaks

