# writes a dataframe object as a bedfile 
# take a dataframe with chr, start, end, as first 3 columns

write_bed <- function(data, filename, ncol = NA){
  require(readr)
  data <- as.data.frame(data)
  if(is.na(ncol)){
    ncol <- ncol(data)
  }
  write_delim(file = filename, delim = "\t", x = data[, 1:ncol], append = F, col_names = F)
  #now, check if bedtools can read the file to ensure proper formatting 
  bedlines <- system(paste("cat ", filename, " | sort -k 1,1 -k2,2n | bedtools merge -i stdin | wc -l", sep = ""), intern = T)%>% 
    readr::parse_number()
  if(bedlines > 0){
    print("Bed format file generated successfully")
  }else{
    print("An error occurred. The bed file was not successfully generated.")
  }
  
} #end write_bed function

#function to intersect bed files with HARs, HAQERs, hCONDELs
overlap_with_HARs <- function(bed_files){
  require(stringr)
  require(tidyverse)
  #HARs and friends
  HARs<- "/Users/alexanderokamoto/Desktop/Capellini_Lab/HARs/HARs_AO_2024_merged_hg38.bed"
  hCONDELs <- "/Users/alexanderokamoto/Desktop/Capellini_Lab/Capellini_Lab_Peak_Sets/Other_Peak_sets/hCONDELs_Xue_McLean_hg38.bed"
  hCONDELs_long <- "/Users/alexanderokamoto/Desktop/Capellini_Lab/Capellini_Lab_Peak_Sets/Other_Peak_sets/hCONDELs_McLean2011_hg38.bed"
  #HAQERs have a methological issue and should be excluded
  #HAQERs <- "/Users/alexanderokamoto/Desktop/Capellini_Lab/Capellini_Lab_Peak_Sets/Other_Peak_sets/haqer.hg38.bed"
  #HARS_all <- "/Users/alexanderokamoto/Desktop/Capellini_Lab/Capellini_Lab_Peak_Sets/Other_Peak_sets/HARs_HAQERS_hCONDELS_hg38.bed"
  HARs_hCONDELs<- "/Users/alexanderokamoto/Desktop/Capellini_Lab/Capellini_Lab_Peak_Sets/Other_Peak_sets/HARs_hCONDELS_hg38.bed"

  #cat /Users/alexanderokamoto/Desktop/Capellini_Lab/HARs/HARs_AO_2024_merged_hg38.bed /Users/alexanderokamoto/Desktop/Capellini_Lab/Capellini_Lab_Peak_Sets/Other_Peak_sets/hCONDELs_Xue_McLean_hg38.bed | sort -k 1,1 -k2,2n | bedtools merge -i stdin -c 4 -o collapse > /Users/alexanderokamoto/Desktop/Capellini_Lab/Capellini_Lab_Peak_Sets/Other_Peak_sets/HARs_hCONDELS_hg38.bed
  
  #make df to store results
  results_df <- data.frame(file = bed_files, set = NA, HAR_overlap = NA, hCONDEL_overlap = NA, hCONDEL_long_overlap = NA,all_overlap = NA)
  
  #iterate over files
  for(i in 1:nrow(results_df)){
    #get simpler name for set 
    name_split <- unlist(str_split(results_df$file[i], pattern = "/"))
    results_df$set[i] <- gsub(pattern = ".bed", replacement = "", x = name_split[length(name_split)])
    
    #perform the overlaps
    results_df$HAR_overlap[i] <- system(paste("bedtools intersect -a ", results_df$file[i], " -b ", HARs, " | wc -l ",
                 sep = ""), intern =T) %>% readr::parse_number()
    #results_df$HAQER_overlap[i] <- system(paste("bedtools intersect -a ", results_df$file[i], " -b ", HAQERs, " | wc -l ",
    #                                          sep = ""), intern =T) %>% readr::parse_number()
    results_df$hCONDEL_overlap[i] <- system(paste("bedtools intersect -a ", results_df$file[i], " -b ", hCONDELs, " | wc -l ",
                                              sep = ""), intern =T) %>% readr::parse_number()
    results_df$hCONDEL_long_overlap[i] <- system(paste("bedtools intersect -a ", results_df$file[i], " -b ", hCONDELs_long, " | wc -l ",
                                                  sep = ""), intern =T) %>% readr::parse_number()
    #use combined bed file in case some HARs/HAQERS/hCONDELs overlap, which happens but is rare.
    results_df$all_overlap[i] <- system(paste("bedtools intersect -a ", results_df$file[i], " -b ", HARs_hCONDELs, " | wc -l ",
                                                  sep = ""), intern =T) %>% readr::parse_number()
  } # end loop

  return(results_df %>% dplyr::select(-file))
} #end overlap_with_HARs function

