#create a function to calculater empiric background distribution from set
calc_bed_overlap_empiric <- function(bed, background = NA, target_bed, nsets){
  #create vector to store results
  background_vals <- rep(NA, nsets)
  #get basic information about input bed set
  total_bed_elements <- system(
    paste("cat ", bed, " | wc -l", sep = ""), intern =T) %>% 
    readr::parse_number()
  total_length <- system(
    paste("cat ", bed, " | awk -F'\t' 'BEGIN{SUM=0}{ SUM+=$3-$2 }END{print SUM}'", sep = ""), intern =T) %>% 
    readr::parse_number()
  avg_length <- total_length/total_bed_elements
  
  #use genomic background if no other background specified. 
  if(is.na(background)){

    #iterate over elements
    for (i in 1:nsets){
      background_vals[i] <- system(
      paste("bedtools random -g ~/Documents/bedtools2/genomes/human.hg38.genome -l ", avg_length, " -n ", total_bed_elements, 
            " | sort -k 1,1 -k2,2n | bedtools intersect -a stdin -b ", target_bed, " | wc -l", sep = ""), intern =T) %>% 
      readr::parse_number()
    }
  } else{
    #iterate over elements
    for (i in 1:nsets){
      background_vals[i] <- system(
        paste("cat ", background, " | sort --random-sort | sed -n '1,", total_bed_elements, 
              "p' | sort -k 1,1 -k2,2n | bedtools intersect -a stdin -b ", target_bed, " | wc -l", sep = ""), intern =T) %>% 
        readr::parse_number()
    }
  }
  background_vals <- background_vals/total_length
  
  real_value <- system(
    paste("bedtools intersect -a ", bed, " -b ", target_bed, " | wc -l", sep = ""), intern =T) %>% 
    readr::parse_number()
  
  pval <- length(which(real_value/total_length > background_vals))/nsets
  
  return(pval)
} #end calc_bed_overlap_empiric function

