#create function to plot bed regions on human skeleton
plot_bed_regions_early <- function(bed_file){
  #load custom functions for analysis
  source("~/Desktop/Capellini_Lab/Weekly_Coding/Skeleton_Heatmap_V1.R")
  bed_df <- read.table(bed_file, sep = "\t")
  
  for(i in 1:nrow(bed_df)){
    current_bed <- bed_df[i,]
    results_df <- read.table("~/Desktop/Capellini_Lab/Weekly_Coding/skeleton_heatmap_beds.txt", header = T)
    for(x in 1:nrow(results_df)){
      results_df$value[x] <- system(paste("echo '", current_bed[1], "\t",  current_bed[2], "\t",  current_bed[3], "' | bedtools intersect -a stdin -b ", results_df$early_file[x], " | wc -l", sep =""), intern =T) %>% 
        readr::parse_number()
    } #end iterate over tissues
      
    plot_skeleton_heatmap(expr_df = results_df %>% dplyr::select(tissue, value), inc.autopods = T, file_name = paste("~/Desktop/Autopod_Skeleton_Figures/", current_bed[4], "_early_skeleton_heatmap", sep = ""), key_label = current_bed[4])
  } #end iterate over beds
} #end plot_bed_regions function

