#create function to return number of genes in window around certain genes
genes_near_feature <- function(feature_bed, dist = 500000, autopod_threshold = 0, threshold_type = "max"){
  require(data.table)
  require(tidyverse)
  #load required functions
  source("~/Desktop/Capellini_Lab/Weekly_Coding/Daniel_HAR_enrichment_functions.R")
  
  #load gene info 
  gene_bed <- "~/Desktop/Capellini_Lab/Capellini_Lab_Peak_Sets/Other_Peak_sets/hg38_refGene.sorted.bed"
  #load gene expression info
  max_gene_expr <- fread(file = "~/Desktop/Capellini_Lab/Human Autopod RNA/human_max_gene_expr.tsv", sep = "\t", header = T)
  colnames(max_gene_expr) <- c("gene", "max_expr", "min_expr")
  
  #pad bed to distance
  pad_bed_orig(gene_bed, dist)
  padded_bed <- gsub(".bed", paste("_padded", dist, ".bed", sep=""), gene_bed) ##Pretty self-explanatory.
  
  #get counts 
  gene_table <- read.delim(gene_bed, sep = "\t", header = F)
  colnames(gene_table) <- c("chr", "start", "end", "gene")
  gene_table$feature_n <- system(paste("sort -k 1,1 -k2,2n ", feature_bed, " | bedtools intersect -a ", padded_bed, " -b stdin -c | awk -F'\t' '{print $5}'", sep = "") , intern =T) %>% 
  readr::parse_number()
  
  if(toupper(threshold_type) == 'MAX'){
    gene_table_reduced <- gene_table %>% 
      dplyr::select(gene, feature_n) %>% 
      distinct() %>% 
      dplyr::filter(feature_n > 0) %>% 
      dplyr::left_join(y = max_gene_expr) %>% 
      dplyr::filter(max_expr >= autopod_threshold) %>%
      dplyr::arrange(-feature_n, -max_expr) 
  }
  if(toupper(threshold_type) == 'MIN'){
    gene_table_reduced <- gene_table %>% 
      dplyr::select(gene, feature_n) %>% 
      distinct() %>% 
      dplyr::filter(feature_n > 0) %>% 
      dplyr::left_join( y = max_gene_expr) %>% 
      dplyr::filter(min_expr >= autopod_threshold) %>%
      dplyr::arrange(-feature_n, -min_expr) 
  }
  
  #cleanup
  system(paste("rm ", padded_bed, sep = ""))
  
  return(gene_table_reduced)
}

#create function to return number of genes in window around certain genes
genes_near_multi_feature <- function(feature_bed_list, dist = 500000){
  
  #load required functions
  source("~/Desktop/Capellini_Lab/Weekly_Coding/Daniel_HAR_enrichment_functions.R")
  
  #load gene info 
  gene_bed <- "~/Desktop/Capellini_Lab/Capellini_Lab_Peak_Sets/Other_Peak_sets/hg38_refGene.sorted.bed"
  
  #get counts 
  gene_table <- read.delim(gene_bed, sep = "\t", header = F)
  colnames(gene_table) <- c("chr", "start", "end", "gene")
  
  #pad bed to distance
  pad_bed_orig(gene_bed, dist)
  padded_bed <- gsub(".bed", paste("_padded", dist, ".bed", sep=""), gene_bed) ##Pretty self-explanatory.
  
  #iterate over bed files
  for (file in feature_bed_list){
    gene_table[, ncol(gene_table) + 1] <- system(paste("bedtools intersect -a ", padded_bed, " -b ", file, " -c | awk -F'\t' '{print $5}'", sep = "") , intern =T) %>% 
      readr::parse_number()
    
    #cleanup
  }
  
  return(unique(gene_table))
}

#compare two DNA sequences and count the number of differences
#if the length of the sequences are not equal, return "999" to prevent R treating NA as a 0 for downstream steps
compare.DNA <- function(x, y){
  count <- 0
  x_bps <- unlist(str_split(x, pattern = ""))
  y_bps <- unlist(str_split(y, pattern = ""))
  if(length(x_bps) == length(y_bps)){
    count <- length(which(sapply(seq(length(x_bps)),
                                 function(i){
                                   x_bps[i] != y_bps[i]
                                 })))
    return(count)
  }else{
    return(999)
  }
}
  

#create a function to compare human-chimp basepairs
compare_human_ape_bps <- function(bedfile, ape = "chimp", mode = "total_differences"){
  #gorilla requires generating a custom genome package
  # library(BSgenomeForge)
  # forgeBSgenomeDataPkgFromUCSC(
  #     genome="gorGor6",
  #     organism="Gorilla gorilla",
  #     pkg_maintainer="Alexander Okamoto <aokamoto@g.harvard.edu>"
  # )
  # devtools::build("./BSgenome.Ggorilla.UCSC.gorGor6")
  # devtools::check_built("./BSgenome.Ggorilla.UCSC.gorGor6")
  # devtools::install_local("./BSgenome.Ggorilla.UCSC.gorGor6")
  
  #load packages
  
  require(tidyverse)
  require(BSgenome.Hsapiens.UCSC.hg38)
  require(BSgenome.Ptroglodytes.UCSC.panTro6)
  require(BSgenome.Ggorilla.UCSC.gorGor6)
  require(Biostrings)
  require(GenomicRanges)
  
  #set values depending on ape for comparison
  #currently only chimp or gorilla accepted
  if(toupper(ape) == "CHIMP"){
    BS_genome <- BSgenome.Ptroglodytes.UCSC.panTro6
    ape_chain <- "~/Desktop/Polymorphisms_Project/LiftOver/Chains/hg38ToPanTro6.over.chain"
  }
  if(toupper(ape) == "GORILLA"){
    BS_genome <- BSgenome.Ggorilla.UCSC.gorGor6
    ape_chain <- "~/Desktop/Polymorphisms_Project/LiftOver/Chains/hg38.gorGor6.all.chain"
  }
  
  #load bedfile and start processing
  bed_table <- read.delim(bedfile, sep = "\t", header = F)
  #add required column names for easier calling later on
  colnames(bed_table)[1:3] <- c("chr", "start", "end")
  bed_table <- bed_table %>% 
    dplyr::filter(chr %in% c(paste("chr", 1:22, sep = ""), "chrX", "chrY"))
  
  #get human DNA sequences
  bed_table$human_seqs <- bed_table %>% 
    dplyr::select(chr, start, end) %>% 
    dplyr::filter(chr %in% c(paste("chr", 1:22, sep = ""), "chrX", "chrY")) %>% 
    makeGRangesFromDataFrame() %>% 
    getSeq(x=BSgenome.Hsapiens.UCSC.hg38) %>% 
    as.character()
  #get lengths of sequence to expect
  bed_table$human_length <- bed_table$end - bed_table$start + 1
  #create stable ID value
  bed_table$ID <- paste(bed_table$chr, bed_table$start, bed_table$end, sep = "")


  #get ape DNA sequences
  
  #get granges of liftover object
  ape_granges <- bed_table %>% 
    dplyr::filter(chr %in% c(paste("chr", 1:22, sep = ""), "chrX", "chrY")) %>% 
    makeGRangesFromDataFrame(keep.extra.columns = TRUE) %>% 
    liftOver(chain = import.chain(ape_chain)) %>% 
    unlist()
  
  #make a dataframe to store extracted bits of sequence
  ape_info <-  ape_granges %>% as.data.frame()
  ape_info$seq <- ape_granges %>% getSeq(x = BS_genome)  %>% 
    as.character()
  ape_concat_info <- ape_info %>% 
    dplyr::select(seq, ID, width) %>% 
    group_by(ID) %>% 
    mutate(ape_seq = paste0(seq, collapse = ""), ape_length = sum(width)) %>% 
    dplyr::select(ID, ape_seq, ape_length) %>% 
    unique()
  
  #combined ape and human bedtables
  combined_table <- merge(bed_table, ape_concat_info, by = 'ID')
  reduced_table <- combined_table %>% 
    dplyr::filter(human_length == ape_length) %>% 
    group_by(ID) %>% 
    mutate(bps_difs = compare.DNA(human_seqs, ape_seq))
  reduced_table$per_bp_difs <- reduced_table$bps_difs/reduced_table$human_length
  if(toupper(mode) == "TOTAL_DIFFERENCES"){
    return(reduced_table$bps_difs)
  }
  if(toupper(mode) == "PER_BP_DIFFERENCES"){
    return(reduced_table$per_bp_difs)
  }
}

#compare polarized DNA sequences and count the number of differences
#if the length of the sequences are not equal, return "999" to prevent R treating NA as a 0 for downstream steps
compare_DNA_polarized <- function(x, y, z){
  count <- 0
  x_bps <- unlist(str_split(x, pattern = ""))
  y_bps <- unlist(str_split(y, pattern = ""))
  z_bps <- unlist(str_split(z, pattern = ""))
  if(length(x_bps) == length(y_bps) && length(x_bps) == length(z_bps)){
    count <- length(which(sapply(seq(length(x_bps)),
                                 function(i){
                                   x_bps[i] != y_bps[i] & y_bps[i] == z_bps[i]
                                 })))
    return(count)
  }else{
    return(999)
  }
}

compare_DNA_polarized("act", "aga", "aca")

