  gene_df <- fread(file = gene_bed, sep = "\t", header = F)
  colnames(gene_df) <- c("chr", "start", "end", "gene")
  temp_gene_set <- "~/Desktop/TEMP_ATAC_DIR/temp_gene_set.bed"
  temp_feature_set <- "~/Desktop/TEMP_ATAC_DIR/temp_feature_set.bed"
  
