  #reduce gene bed to expressed genes 
  if(toupper(threshold_type) == 'MAX'){
    gene_df_subset <- gene_df %>% 
      dplyr::filter(gene %in% max_gene_expr$gene[which(max_gene_expr$max_expr >= autopod_threshold)]) %>% 
      unique()
    write_bed(gene_df_subset, filename = temp_gene_set, ncol = 4)
