#create a function to test for a skew in the number of HAR, HAQER, and hCONDELs overlapping a set
#the idea here is that an excess of hCONDELs might be a signal of lost/reduced enhancer activity
HAR_chi_sqr_bed <- function(bed){
  HARs<- "/Users/alexanderokamoto/Desktop/Capellini_Lab/HARs/HARs_list_hg38.bed"
  hCONDELs <- "/Users/alexanderokamoto/Desktop/Capellini_Lab/Capellini_Lab_Peak_Sets/Other_Peak_sets/hCONDELS_Xue_2023_hg38.bed"
  HAQERs <- "/Users/alexanderokamoto/Desktop/Capellini_Lab/Capellini_Lab_Peak_Sets/Other_Peak_sets/haqer.hg38.bed"
  
  #perform overlaps and get counts
  HAR_n <- system(paste("bedtools intersect -a ", bed, " -b ", HARs, " | wc -l ",
                        sep = ""), intern =T) %>% readr::parse_number()
  HAQER_n <- system(paste("bedtools intersect -a ", bed, " -b ", HAQERs, " | wc -l ",
                          sep = ""), intern =T) %>% readr::parse_number()
  hCONDEL_n <- system(paste("bedtools intersect -a ", bed, " -b ", hCONDELs, " | wc -l ",
                            sep = ""), intern =T) %>% readr::parse_number()
  total_HARS <- 3113
  total_HAQERs <- 1581
  total_hCONDELs <- 10031
  total <- total_HARS + total_HAQERs + total_hCONDELs
  remaining_HARs <- total_HARS - HAR_n
  remaining_HAQERs <- total_HAQERs - HAQER_n
  remaining_hCONDELs <- total_hCONDELs - hCONDEL_n
  
  #make dataframe for Chi-Squared Test
  test_df <- data.frame(HARS = c(remaining_HARs, HAR_n),
                        HAQERS = c(remaining_HAQERs, HAQER_n),
                        HCONDELS = c(remaining_hCONDELs, hCONDEL_n))
  
  rownames(test_df) <- c("not_found", "found") 
  
  #run the test
  chisq <- chisq.test(test_df)
  print(test_df)
  return(chisq)
  
}

HAR_chi_sqr_bed("~/Desktop/Capellini_Lab/Human_ATAC/autopod_only_top_candidates_clean_hg38.bed")


#function to determine which genes are located near multiple peaks

complex_regulated_genes <- function(bed_command, dist){
  #load required packages
  require(tidyverse)
  
  #reference bed file of gene positions
  refgene_bed <- "~/Desktop/Capellini_Lab/Capellini_Lab_Peak_Sets/Other_Peak_sets/hg38_refGene.sorted.bed"
  
  pad_bed_orig(refgene_bed, padding = dist)
  padded_gene_bed <- paste("~/Desktop/Capellini_Lab/Capellini_Lab_Peak_Sets/Other_Peak_sets/hg38_refGene.sorted_padded", dist,".bed", sep = "")
  
  #save bed file as temporary bed with known location
  temp_bed <- "~/Desktop/TEMP_ATAC_DIR/complex_reg_temp.bed"
  system(paste(bed_command, ">", temp_bed <- "~/Desktop/TEMP_ATAC_DIR/complex_reg_temp.bed"))
  
  temp_bed_overlapped <- "~/Desktop/TEMP_ATAC_DIR/complex_reg_tem_overlapped.bed"
  system(paste("bedtools intersect -a ", padded_gene_bed, " -b ", temp_bed, " -c > ", temp_bed_overlapped, sep = ""))
  temp_feature_df <- fread(file = temp_bed_overlapped, sep = "\t", header = F) 
  #add details and cleanup resulting DF
  colnames(temp_feature_df) <- c("chr", "start", "end", "hgnc_symbol", "overlaps")
  temp_feature_df <- temp_feature_df %>% dplyr::filter(overlaps > 1) %>% dplyr::arrange(desc(overlaps))
    
  return(temp_feature_df)
  #cleanup 
  system(paste("rm", padded_bed))
  system(paste("rm", temp_bed))
}

