#repeat for multiple bed files
complex_regulated_genes_multiple <- function(bed_command_list, ID_list, dist, autopod_threshold = 5){
  #load required packages
  require(tidyverse)
  
  #reference bed file of gene positions
  temp_gene_set <- "~/Desktop/TEMP_ATAC_DIR/temp_gene_set.bed"
  refgene_bed <- "~/Desktop/Capellini_Lab/Capellini_Lab_Peak_Sets/Other_Peak_sets/hg38_refGene.sorted.bed"
  gene_df <- fread(file = refgene_bed, sep = "\t", header = F)
  colnames(gene_df) <- c("chr", "start", "end", "gene")
  
  #load gene expression info
  max_gene_expr <- fread(file = "~/Desktop/Capellini_Lab/Human Autopod RNA/human_max_gene_expr.tsv", sep = "\t", header = T)
  colnames(max_gene_expr) <- c("gene", "max_expr", "min_expr")
  
  gene_df_subset <- gene_df %>% 
    dplyr::filter(gene %in% max_gene_expr$gene[which(max_gene_expr$min_expr >= autopod_threshold)]) %>% 
    unique()
  write_bed(gene_df_subset, filename = temp_gene_set, ncol = 4)
  
  pad_bed_orig(temp_gene_set, padding = dist)
  padded_gene_bed <- paste("~/Desktop/TEMP_ATAC_DIR/temp_gene_set_padded", dist,".bed", sep = "")
  
  results_df <- data.frame()
  
  for(i in 1:length(bed_command_list)){
    bed_command <- bed_command_list[i]
    #save bed file as temporary bed with known location
    temp_bed <- "~/Desktop/TEMP_ATAC_DIR/complex_reg_temp.bed"
    system(paste(bed_command, ">", temp_bed <- "~/Desktop/TEMP_ATAC_DIR/complex_reg_temp.bed"))
    
    temp_bed_overlapped <- "~/Desktop/TEMP_ATAC_DIR/complex_reg_tem_overlapped.bed"
    system(paste("bedtools intersect -a ", padded_gene_bed, " -b ", temp_bed, " -c > ", temp_bed_overlapped, sep = ""))
    temp_feature_df <- fread(file = temp_bed_overlapped, sep = "\t", header = F) 
    #add details and cleanup resulting DF
    colnames(temp_feature_df) <- c("chr", "start", "end", "hgnc_symbol", ID_list[i])
    if(nrow(results_df) >= 1){
      results_df <- merge(results_df,temp_feature_df)
    } else{
      results_df <- temp_feature_df
    }
    
    system(paste("rm", temp_bed))
  }
  return(results_df)
  #cleanup 
  system(paste("rm", padded_bed))
}

