#create function to perform GREAT enrichment on a bedfile and output results comparable to GREAT browser application
#note: this does not output ensembl genes and mouse phenotype single KO results 
#genome can be set as "hg19" or "mm10" as desired
bed_GREAT_enrich <- function(bedfile, genome = "hg38"){
  #load packages required
  require(regioneR)
  require(rGREAT)
  require(tidyverse)
  #read bed as GRanges object
  bed  <- toGRanges(bedfile)
  
  cluster_go_summary <- data.frame()
  #perform GREAT enrichment
  raw_enrichments <- submitGreatJob(bed, genome = genome) %>% 
    getEnrichmentTables(
      ontology = c("GO Molecular Function", "GO Biological Process", "GO Cellular Component", "Human Phenotype", "Mouse Phenotype"))
  
  #get results for each ontology
  MP <- raw_enrichments["GO Molecular Function"][[1]]
  MP$Ontology <- "GO Molecular Function"
  BP <- raw_enrichments["GO Biological Process"][[1]]
  BP$Ontology <- "GO Biological Process"
  CC <- raw_enrichments["GO Cellular Component"][[1]]
  CC$Ontology <- "GO Cellular Component"
  hs_pheno <- raw_enrichments["Human Phenotype"][[1]]
  hs_pheno$Ontology <- "Human Phenotype"
  mm_pheno <- raw_enrichments["Mouse Phenotype"][[1]]
  mm_pheno$Ontology <- "Mouse Phenotype"
  
  #merge and filter ontology results 
  results <- rbind(MP, BP, CC, hs_pheno, mm_pheno) %>% 
    dplyr::filter(Hyper_Adjp_BH < 0.05) %>% 
    dplyr::filter(Binom_Adjp_BH < 0.05) %>% 
    dplyr::filter(Binom_Fold_Enrichment >= 2) %>% 
    arrange(Ontology, Binom_Adjp_BH)
  
  #if GO enrichments, add label
    if(nrow(cluster_go_summary > 0)){
      cluster_go_summary$gene_set <- paste("Cluster_", i, sep ="")
    #otherwise, add a marker stating no results found
    }else{
      cluster_go_summary <- data.frame(ID =NA, 
                                       Description = "NO GO ENRICHMENTS", 
                                       GeneRatio = NA, 
                                       BgRatio = NA,
                                       RichFactor = NA,
                                       FoldEnrichment = NA,
                                       zScore = NA,
                                       pvalue = NA, 
                                       p.adjust = NA, 
                                       qvalue =NA, 
                                       geneID = NA, 
                                       Count = NA, 
                                       gene_set = paste("Cluster_", i, sep =""))
    }
  
  #return result
  return(results)
}

