  #create a version of the svg file to edit
  hand_skeleton_temp <- hand_skeleton
  foot_skeleton_temp <- foot_skeleton
  #replace with colors
  
  expr_df$color <- "black"
  
  #check if min/max colors set
  if(is.na(min_color_value)){
    min_color_value <- min (expr_df$value )
  }else{
    if(min(expr_df$value ) < min_color_value ){
      print("ERROR: VALUES BELOW MINIMUM FOUND")
    }
  }
  if(is.na(max_color_value)){
    max_color_value <- max(expr_df$value)
  }else{
    if( max(expr_df$value) > max_color_value ){
      print("ERROR: VALUES ABOVE MAXIMUM FOUND")
    }
  }
  
  #create color range
  #if centered, middle value is gray, otherwise, use red to blue
  if(center == T){
    fun_color_range1 <- colorRampPalette(c("gray", "red"))   
    fun_color_range2 <- colorRampPalette(c("blue", "gray"))  
    if(is.na(center_color_value)){
      my_colors <- c(fun_color_range2(50), "gray", fun_color_range1(50))
    } else{
      min_dist <- sqrt( ( min_color_value - center_color_value) ^2 )
      max_dist <- sqrt( ( max_color_value - center_color_value) ^2 )
      min_count <- round(min_dist/(max_dist + min_dist)*100, digits = 0)
      max_count <- 100 - min_count
      my_colors <- c(fun_color_range2(100)[(100-min_count-1):100], fun_color_range1(100)[2:max_count + 1])
      
    }
    
  } else{
    fun_color_range <- colorRampPalette(c("blue", "red"))   
    my_colors <- fun_color_range(101)
  }
  
  #determine range of values
  
  for (i in 1:nrow(expr_df)){
    distance <- sqrt( ( min_color_value - max_color_value ) ^2 )
    color_pos <- round(sqrt((expr_df$value[i] - min_color_value)^2)/distance *100, digits = 0) + 1
    expr_df$color[i] <- my_colors[color_pos]
    hand_skeleton_temp <- gsub(pattern = paste('z" fill=\"black\"/>\n', expr_df$tissue[i], sep = ""), replacement = paste('z" fill=\"', expr_df$color[i], '\"/>\n', expr_df$tissue[i], sep = ""), x = hand_skeleton_temp)
    foot_skeleton_temp <- gsub(pattern = paste('z" fill=\"black\"/>\n', expr_df$tissue[i], sep = ""), replacement = paste('z" fill=\"', expr_df$color[i], '\"/>\n', expr_df$tissue[i], sep = ""), x = foot_skeleton_temp)
  }
  
  #make the plot
  png(filename=paste("~/Desktop/Autopod_Skeleton_Figures/", file_name, ".png", sep = ""), width = 360, height = 360)
  hand_grob <- svgparser::read_svg(hand_skeleton_temp)
  foot_grob <- svgparser::read_svg(foot_skeleton_temp)
  grid::grid.newpage()
  seq()
  
  plot(x = 1:100, y = rep(0, 100),                                               # Example plot
       pch = 16,
       col = my_colors,
       ylim = c(0, 10), 
       axes = FALSE, 
       xlab = 'n', 
       ylab = 'n', 
       ann = FALSE)
  #axis(1)
  pushViewport(viewport(angle = 90, width=0.4,height=0.4, x = 0.35))
  grid::grid.draw(hand_grob)
  #plot foot
  pushViewport(viewport(angle = -90, width=1.3, height=1.3, y = -0.7, x = 0.65))
  grid::grid.draw(foot_grob)
  # Add scale min and max values
  #text(5, 1, as.character(round(min(expr_df$value), digits = 2)))
  #text(95, 1, as.character(round(max(expr_df$value), digits = 2)))
  text(5, 1, as.character(signif(min_color_value, 3)))
  text(95, 1, as.character(signif(max_color_value, 3)))
  opt_text_i <- paste("italic(", opt_text, ")", sep ="")
  text(50, 11, bquote(
    italic(.(opt_text))), cex = 3)
  
  # Back to the original color
  par(bg = "white")
  dev.off()
} #end function


