  fun_color_range <- colorRampPalette(c("blue", "red"))    
  my_colors <- fun_color_range(101)
  
  #create a version of the svg file to edit
  hand_skeleton_early <- hand_skeleton
  foot_skeleton_early <- foot_skeleton
  
  #create a version of the svg file to edit
  hand_skeleton_late <- hand_skeleton
  foot_skeleton_late <- foot_skeleton
  
  #edit files 
  sampleType = c("FM1", "FM2", "FM3", "FM4", "FM5", "FP1", "FP2", "FP3", "FP4", "FP5", "HM1", "HM2", "HM3", "HM4", "HM5", "HP1", "HP2", "HP3", "HP4", "HP5")
  early_samples <- paste(sampleType, "Early", sep = "_")
  late_samples <- paste(sampleType, "Late", sep = "_")
  for (i in 1:length(sampleType)){
    hand_skeleton_early <- gsub(x = hand_skeleton_early, pattern = sampleType[i], replacement = early_samples[i])
    foot_skeleton_early <- gsub(x = foot_skeleton_early, pattern = sampleType[i], replacement = early_samples[i])
    hand_skeleton_late <- gsub(x = hand_skeleton_late, pattern = sampleType[i], replacement = late_samples[i])
    foot_skeleton_late <- gsub(x = foot_skeleton_late, pattern = sampleType[i], replacement = late_samples[i])
  }
  
  #replace with colors
  
  expr_df$color <- "black"
  
  
  #determine range of values
  
  for (i in 1:nrow(expr_df)){
    distance <- sqrt( ( min ( expr_df$value ) - max(expr_df$value) ) ^2 )
    color_pos <- round(sqrt((expr_df$value[i] - min(expr_df$value))^2)/distance *100, digits = 0) + 1
    expr_df$color[i] <- my_colors[color_pos]
    hand_skeleton_early <- gsub(pattern = paste('z" fill=\"black\"/>\n', expr_df$tissue[i], sep = ""), replacement = paste('z" fill=\"', my_colors[color_pos], '\"/>\n', expr_df$tissue[i], sep = ""), x = hand_skeleton_early)
    foot_skeleton_early <- gsub(pattern = paste('z" fill=\"black\"/>\n', expr_df$tissue[i], sep = ""), replacement = paste('z" fill=\"', my_colors[color_pos], '\"/>\n', expr_df$tissue[i], sep = ""), x = foot_skeleton_early)
    hand_skeleton_late <- gsub(pattern = paste('z" fill=\"black\"/>\n', expr_df$tissue[i], sep = ""), replacement = paste('z" fill=\"', my_colors[color_pos], '\"/>\n', expr_df$tissue[i], sep = ""), x = hand_skeleton_late)
    foot_skeleton_late <- gsub(pattern = paste('z" fill=\"black\"/>\n', expr_df$tissue[i], sep = ""), replacement = paste('z" fill=\"', my_colors[color_pos], '\"/>\n', expr_df$tissue[i], sep = ""), x = foot_skeleton_late)
  }
  
  hand_grob_early <- svgparser::read_svg(hand_skeleton_early)
  foot_grob_early  <- svgparser::read_svg(foot_skeleton_early)
  hand_grob_late <- svgparser::read_svg(hand_skeleton_late)
  foot_grob_late <- svgparser::read_svg(foot_skeleton_late)
  #make the plot
  
  png(filename=paste("~/Desktop/Autopod_Skeleton_Figures/", file_name, "_early.png", sep = ""), width = 360, height = 360)
  
  grid::grid.newpage()
  
  #axis(1)
  pushViewport(viewport(angle=90, width=0.4,height=0.4, x = 0.35))
  grid::grid.draw(hand_grob_early)
  #plot foot
  pushViewport(viewport(angle = -90, width=1.3, height=1.3, y = -0.7, x = 0.65))
  grid::grid.draw(foot_grob_early)
  par(bg = "white") #make background gray
  #plot hand (late)
  #pushViewport(viewport(angle=90, width=0.2,height=0.2, y = 0.2, x = 0.35))
  #grid::grid.draw(hand_grob_late)
  #plot foot (late)
  #pushViewport(viewport(angle = -90, width=0.65, height=0.65, y = -1.2, x = 0.65))
  #grid::grid.draw(foot_grob_late)
  dev.off()
  
  
  png(filename=paste("~/Desktop/Autopod_Skeleton_Figures/", file_name, "_late.png", sep = ""), width = 360, height = 360)
  
  grid::grid.newpage()
  seq()
  
  plot(x = 1:100, y = rep(0, 100),                                               # Example plot
       pch = 16,
       col = my_colors,
       ylim = c(0, 10), 
       axes = FALSE, 
       xlab = 'n', 
       ylab = 'n', 
       ann = FALSE)
  #axis(1)
  pushViewport(viewport(angle=90, width=0.4,height=0.4, x = 0.35))
  grid::grid.draw(hand_grob_late)
  #plot foot
  pushViewport(viewport(angle = -90, width=1.3, height=1.3, y = -0.7, x = 0.65))
  grid::grid.draw(foot_grob_late)
  #plot hand (late)
  #pushViewport(viewport(angle=90, width=0.2,height=0.2, y = 0.2, x = 0.35))
  #grid::grid.draw(hand_grob_late)
  #plot foot (late)
  #pushViewport(viewport(angle = -90, width=0.65, height=0.65, y = -1.2, x = 0.65))
  #grid::grid.draw(foot_grob_late)
  # Add scale min and max values
  text(5, 1, as.character(round(min(expr_df$value), digits = 2)))
  text(95, 1, as.character(round(max(expr_df$value), digits = 2)))
  text(50, 11, bquote(
    italic(.(opt_text))), cex = 3)
  
  # Back to the original color
  par(bg = "white")
  dev.off()
  
  plt_early <- image_read(path = paste("~/Desktop/Autopod_Skeleton_Figures/", file_name, "_early.png", sep = "")) %>%
    image_ggplot() + theme(plot.margin = unit(c(-2,-1,-4,-2), "cm"))
  plt_late <- image_read(path = paste("~/Desktop/Autopod_Skeleton_Figures/", file_name, "_late.png", sep = "")) %>%
    image_ggplot() + theme(plot.margin = unit(c(-2,-1,-4,-2), "cm"))
  
  final_plt <- plot_grid(plt_early, plt_late, nrow = 2 , ncol = 1, labels = c("Early", "Late"), byrow = T)
  
  ggsave(final_plt, device = "png", filename = paste(file_name, ".png", sep = ""), path = "~/Desktop/Autopod_Skeleton_Figures/", width = 5, height = 10)
  
  #cleanup
  system(paste("rm ~/Desktop/Autopod_Skeleton_Figures/", file_name, "_early.png", sep = ""))
  system(paste("rm ~/Desktop/Autopod_Skeleton_Figures/", file_name, "_late.png", sep = ""))
  
} #end function


#perform Gene Ontology (GO) enrichment
#requires:
#a universe of ensembl IDs for the background gene set
#a species database (either human or mouse presumable) to get gene information from
#a set of clustering results containing ensemble gene IDs in a "gene_id" column and cluster in a "cluster" column
#the name of the csv file to save the results to

cluster_go_analysis <- function(universe, database, cluster_results, outfile){
  GO_results <- enrichGO(gene = cluster_results$gene_id, 
                         universe = universe,
                         keyType = "ENSEMBL",
                         OrgDb = database, 
                         ont = "BP", 
                         pAdjustMethod = "BH", 
                         qvalueCutoff = 0.05, 
                         readable = TRUE) %>% as.data.frame()
  GO_results$gene_set <- "ALL_DEGs"
  for(i in min(cluster_results$cluster):max(cluster_results$cluster)){
    #get genes specific to the cluster
    sigOE_genes <- cluster_results %>% dplyr::filter(cluster == i) %>%  pull(gene_id)
    #get test results
    cluster_go_summary <- enrichGO(gene = sigOE_genes, 
                                   universe = universe,
                                   keyType = "ENSEMBL",
                                   OrgDb = database, 
                                   ont = "BP", 
                                   pAdjustMethod = "BH", 
                                   qvalueCutoff = 0.05, 
                                   readable = TRUE) %>% as.data.frame()
    #if GO enrichments, add label
    if(nrow(cluster_go_summary > 0)){
      cluster_go_summary$gene_set <- paste("Cluster_", i, sep ="")
      #otherwise, add a marker stating no results found
    }else{
      cluster_go_summary <- data.frame(ID =NA, 
                                       Description = "NO GO ENRICHMENTS", 
                                       GeneRatio = NA, 
                                       BgRatio = NA,
                                       RichFactor = NA,
                                       FoldEnrichment = NA,
                                       zScore = NA,
                                       pvalue = NA, 
                                       p.adjust = NA, 
                                       qvalue =NA, 
                                       geneID = NA, 
                                       Count = NA, 
                                       gene_set = paste("Cluster_", i, sep =""))
    }
    GO_results <- rbind(GO_results, cluster_go_summary)
    
  }
  #modify ratios to prevent excel from reading them as dates
  GO_results$GeneRatio <- paste("'", GO_results$GeneRatio, "'", sep ="")
  write.csv(GO_results, file = outfile, row.names = F)
  
  
} #end function

human_to_mouse_gene <- function(human_gene_list){
  require(tidyverse)
  #load conversion dataset
  ortholog_table <- read.table(file = "~/Desktop/Capellini_Lab/Weekly_Coding/human_mouse_orthologs.txt", header = T, sep = "\t")
  #find orthologs
  mouse_genes <- ortholog_table$mouse_gene_id[which(ortholog_table$human_gene_id %in% human_gene_list)]
  #return orthlogs
  return(mouse_genes)
}

mouse_to_human_gene <- function(mouse_gene_list){
  require(tidyverse)
  #load conversion dataset
  ortholog_table <- read.table(file = "~/Desktop/Capellini_Lab/Weekly_Coding/human_mouse_orthologs.txt", header = T, sep = "\t")
  #find orthologs
  human_genes <- ortholog_table$human_gene_id[which(ortholog_table$mouse_gene_id %in% mouse_gene_list)]
  #return orthlogs
  return(human_genes)
}

#make a function to plot human gene expression quickly
plot_human_gene <- function(gene, timepoint = "COMBINED", gene_id_type = "SYMBOL"){
  #load packages
  require(tidyverse)
  require(data.table)
  
  #timepoint should be any of: "EARLY", "LATE", "BOTH", "COMBINED"
  #gene_id_type should be either "SYMBOL" or "ENSEMBL"
  
  #make sure expected case
  gene <- toupper(gene)
  timepoint <- toupper(timepoint)
  gene_id_type <- toupper(gene_id_type)
  
  #load in normalized counts data
  norm_counts_longer <- fread(file = "~/Desktop/Capellini_Lab/Human Autopod RNA/human_normalized_counts.tsv", sep = "\t", header = T)
  sampleMetaData <- fread(file = "~/Desktop/Capellini_Lab/Human Autopod RNA/human_sampleMetaData.tsv", sep = "\t", header = T)
  
  #filter by gene of interest
  if(gene_id_type == "ENSEMBL"){
    norm_counts_longer <- norm_counts_longer %>% dplyr::left_join(y = sampleMetaData, by = join_by(name == sample)) %>% dplyr::filter(ensembl_gene_id == gene)
  }
  if(gene_id_type == "SYMBOL"){
    norm_counts_longer <- norm_counts_longer %>% dplyr::left_join(y = sampleMetaData, by = join_by(name == sample)) %>% dplyr::filter(hgnc_symbol == gene)
  }
  
  #perform correct timepoint analysis
  if(timepoint == "COMBINED"){
    norm_counts_longer <- norm_counts_longer %>% group_by(ensembl_gene_id, sampleType, hgnc_symbol) %>% summarize(avg = mean(count)) %>% unique()
    plot_autopod_expression(norm_counts_longer %>% 
                              dplyr::select(sampleType, avg) %>% dplyr::rename(tissue = sampleType, value = avg), 
                            file_name = paste("human_", norm_counts_longer$hgnc_symbol[1], "_expr_", timepoint, sep = ""), opt_text = norm_counts_longer$hgnc_symbol[1])
  }
  
  #perform correct timepoint analysis
  if(timepoint == "EARLY"){
    norm_counts_longer <- norm_counts_longer %>% dplyr::filter(timepoint == "Early") %>% group_by(ensembl_gene_id, sampleType, hgnc_symbol) %>% summarize(avg = mean(count)) %>% unique()
    plot_autopod_expression(norm_counts_longer %>% 
                              dplyr::select(sampleType, avg) %>% dplyr::rename(tissue = sampleType, value = avg), 
                            file_name = paste("human_", norm_counts_longer$hgnc_symbol[1], "_expr_", timepoint, sep = ""), opt_text = norm_counts_longer$hgnc_symbol[1])
  }
  
  #perform correct timepoint analysis
  if(timepoint == "LATE"){
    norm_counts_longer <- norm_counts_longer %>% dplyr::filter(timepoint == "Late") %>% group_by(ensembl_gene_id, sampleType, hgnc_symbol) %>% summarize(avg = mean(count)) %>% unique()
    plot_autopod_expression(norm_counts_longer %>% 
                              dplyr::select(sampleType, avg) %>% dplyr::rename(tissue = sampleType, value = avg), 
                            file_name = paste("human_", norm_counts_longer$hgnc_symbol[1], "_expr_", timepoint, sep = ""), opt_text = norm_counts_longer$hgnc_symbol[1])
  }
  #perform correct timepoint analysis
  if(timepoint == "BOTH"){
    norm_counts_longer <- norm_counts_longer %>% group_by(ensembl_gene_id, sample_tp, hgnc_symbol) %>% summarize(avg = mean(count)) %>% unique()
    plot_autopod_tp_expression(norm_counts_longer %>% 
                                 dplyr::select(sample_tp, avg) %>% dplyr::rename(tissue = sample_tp, value = avg), 
                               file_name = paste("human_", norm_counts_longer$hgnc_symbol[1], "_expr_", timepoint, sep = ""), opt_text = norm_counts_longer$hgnc_symbol[1])
  }
  
  return(norm_counts_longer$hgnc_symbol[1])
} #end plot_human_gene function

