correct_multiinter <- function(file_list, save_bed = F, output_bed_name = NA){
  #determine number of bed files 
  n_files <- length(file_list)
  
  #perform the multinter operation
  multiinter_bed <- "~/Desktop/temp_multiinter.bed"
  multiinter_merged_bed <- "~/Desktop/temp_multiinter_merged.bed"
  system(paste("bedtools multiinter -i ", paste(file_list, collapse = " "),
               " > ", multiinter_bed, collapse = ""))
  multiinter_bed_df <- read.table(multiinter_bed)
  
  #create the merged file and intersect with the multiinter file
  system(paste("cat ", paste(file_list, collapse = " "), " | sort -k 1,1 -k2,2n | bedtools merge -i stdin | bedtools intersect -a stdin -b ", multiinter_bed,  " -wa -wb > ", multiinter_merged_bed, sep = ""))
  
  # this outputs the cleaned table with the merged regions and combined total membership
  # we group by the merged bed coordinates and then get the maximum of presence/absense of a peak in each bed bed file. 
  multiinter_merged_bed_df <- read.table(multiinter_merged_bed)
  
  multiinter_merged_bed_df_cleaned <- multiinter_merged_bed_df %>% dplyr::select(c(1:3), (ncol(multiinter_merged_bed_df) - n_files + 1):ncol(multiinter_merged_bed_df)) %>% group_by(V1, V2, V3) %>% summarize_at(1:n_files, max)
  unlist(multiinter_merged_bed_df_cleaned[1, 4:ncol(multiinter_merged_bed_df_cleaned)])
  
  #count number of intersection
  multiinter_merged_bed_df_cleaned$num <- apply(multiinter_merged_bed_df_cleaned[, 4:ncol(multiinter_merged_bed_df_cleaned)],FUN = sum, MARGIN = 1)
  
  # use a custom function to reconstruct the list of bed files (1:n) and normally output by bedtools multiinter.
  
  multiinter_coords <- function(xlist){
    paste(which(unlist(xlist) ==1), collapse = ",")
  }
  
  multiinter_merged_bed_df_cleaned$list <- apply(multiinter_merged_bed_df_cleaned[, 4:ncol(multiinter_merged_bed_df_cleaned)],FUN = multiinter_coords, MARGIN = 1)
  
  #reorder output
  multiinter_merged_bed_df_cleaned <- multiinter_merged_bed_df_cleaned %>% relocate(num, .after = V3) %>% relocate(list, .after = num)
  
  if(save_bed){
    
    write_delim(x = multiinter_merged_bed_df_cleaned, file = output_bed_name, delim = "\t", col_names = F)
  }
  
  #cleanup temporary files
  system(paste("rm ", multiinter_bed, collapse = ""))
  system(paste("rm ", multiinter_merged_bed, collapse = ""))
  
  return(multiinter_merged_bed_df_cleaned)
} 

plot_many_human_genes <- function(gene_list, file_name, plot_new = TRUE){
  require("png")
  require(data.table)
  require(tidyverse)
  images_df <- data.frame(gene = toupper(gene_list), plot_file = NA)
  norm_counts_longer <- fread(file = "~/Desktop/Capellini_Lab/Human Autopod RNA/human_normalized_counts.tsv", sep = "\t", header = T)
  
  #determine number of pages to print output on 
  pages <- ceiling((length(gene_list) / 25 ))
  
  norm_counts_longer2 <- norm_counts_longer %>% 
    group_by(ensembl_gene_id, hgnc_symbol) %>% 
    summarize(avg = mean(count)) %>% 
    unique() %>%
    dplyr::select(hgnc_symbol, avg) %>% 
    rename(gene = hgnc_symbol, value = avg)
  
  images_df <- images_df %>% left_join(y = norm_counts_longer2, by = join_by(gene)) %>% dplyr::arrange(desc(value))
  
  #return a single page of results if number of genes is sufficently small
  if(pages == 1){
    # setup plot
    dev.off()
    par(mar=rep(0,4)) # no margins
    # layout the plots into a matrix w/ 12 columns, by row
    layout(matrix(1:length(gene_list), ncol=min(c(5, length(gene_list))), byrow=TRUE))
    
    for(i in 1:length(gene_list)){
      if(plot_new == T){
        plot_human_gene(gene = images_df$gene[i], timepoint = "COMBINED")
      }
      images_df$plot_file[i] = paste("~/Desktop/Autopod_Skeleton_Figures/human_", images_df$gene[i], "_expr_COMBINED.png", sep = "")
      # do the plotting
      plot(NA, xlim=0:1, ylim=0:1, bty = "n", axes = 0, xaxs= 'i',yaxs= 'i')
      rasterImage(readPNG(images_df$plot_file[i]),0,0,1,1)
    }
    dev.print(device = png, paste("~/Desktop/Autopod_Skeleton_Figures/", file_name, ".png", sep = ""), width = 7, height = 5, unit = "in", res =1200)
  } #end "if(pages == 1)" condition
  #return a single page of results if number of genes is sufficently small
  if(pages > 1){
    for(x in 0:(pages - 1)){
      images_df2 <- images_df[(1 + (25*x)):min((25*(x + 1)), length(gene_list)), ]
      # setup plot
      dev.off()
      par(mar=rep(0,4)) # no margins
      # layout the plots into a matrix w/ 12 columns, by row
      col_numb=min(c(5, length(images_df2$gene)))
      layout(matrix(1:(ceiling(length(images_df2$gene)/col_numb)*col_numb), ncol=col_numb, byrow=TRUE))
      
      for(i in 1:length(images_df2$gene)){
        if(plot_new == T){
          plot_human_gene(gene = images_df2$gene[i], timepoint = "EARLY")
        }
        images_df2$plot_file[i] = paste("~/Desktop/Autopod_Skeleton_Figures/human_", images_df2$gene[i], "_expr_EARLY.png", sep = "")
        # do the plotting
        plot(NA, xlim=0:1, ylim=0:1, bty = "n", axes = 0, xaxs= 'i',yaxs= 'i')
        try(rasterImage(readPNG(images_df2$plot_file[i]),0,0,1,1))
      }
      dev.print(device = png, paste("~/Desktop/Autopod_Skeleton_Figures/", file_name, "_", x + 1, ".png", sep = ""), width = 7, height = 5, unit = "in", res =1200)
      
    }
    print("Generated multiple pages of results")
  } #end "if(pages > 1)" condition
  
} #end function

