      results_df$value[x] <- system(paste("echo '", current_bed[1], "\t",  current_bed[2], "\t",  current_bed[3], "' | bedtools intersect -a stdin -b ", results_df$early_file[x], " | wc -l", sep =""), intern =T) %>% 
        readr::parse_number()
