    plot_skeleton_heatmap(expr_df = results_df %>% dplyr::select(tissue, value), inc.autopods = T, file_name = paste("~/Desktop/Autopod_Skeleton_Figures/", current_bed[4], "_early_skeleton_heatmap", sep = ""), key_label = current_bed[4])
  } #end iterate over beds
} #end plot_bed_regions function

