#make a function to run command line liftover in R

liftover_to_hg38 <- function(bedfile, chain = "hg19tohg38"){
  
  #current chain options include hg19tohg38, hg38tohg19, hg19tohg38, hg18tohg38, mm10tohg38, chm13tohg38
  
  #load custom functions for analysis
  #source("~/Desktop/Capellini_Lab/Weekly_Coding/Skeleton_Heatmap_V1.R")
  
  #make sure capitalization errors aren't an issue
  chain <- toupper(chain)
  
  if(chain == "HG19TOHG38"){
    #make sure genome version is correct
    if(length(grep("hg19", bedfile)) == 0){
      bedfile_temp <- gsub(pattern = ".bed", replacement = "_hg19.bed", x = bedfile, ignore.case = T)
      print("Warning: genome version not specified, assuming hg19")
    }else{
      bedfile_temp <- bedfile
    }
    #input is a bedfile with "_hg19" in the name
    #note liftover will fail if start = end for a given region
    hg38_bed <- gsub(pattern = "_hg19", replacement = "_hg38", x = bedfile_temp, ignore.case = T)
    hg38_bed_unmapped <- gsub(pattern = "_hg19", replacement = "unmapped_to_hg38", x = bedfile_temp, ignore.case = T)
    #run the liftover
    system(paste("~/Desktop/Polymorphisms_Project/LiftOver/liftOver", bedfile, "~/Desktop/Polymorphisms_Project/LiftOver/Chains/hg19ToHg38.over.chain", hg38_bed, hg38_bed_unmapped, sep = " "))
    print("Liftover completed")
    return(hg38_bed)
  }
  if(chain == "HG38TOHG19"){
    #make sure genome version is correct
    if(length(grep("hg38", bedfile)) == 0){
      bedfile_temp <- gsub(pattern = ".bed", replacement = "_hg38.bed", x = bedfile, ignore.case = T)
      print("Warning: genome version not specified, assuming hg38")
    }else{
      bedfile_temp <- bedfile
    }
    #input is a bedfile with "_hg38" in the name
    #note liftover will fail if start = end for a given region
    hg19_bed <- gsub(pattern = "_hg38", replacement = "_hg19", x = bedfile_temp, ignore.case = T)
    hg19_bed_unmapped <- gsub(pattern = "_hg38", replacement = "unmapped_to_hg19", x = bedfile_temp, ignore.case = T)
    #run the liftover
    system(paste("~/Desktop/Polymorphisms_Project/LiftOver/liftOver", bedfile, "~/Desktop/Polymorphisms_Project/LiftOver/Chains/hg38ToHg19.over.chain", hg19_bed, hg19_bed_unmapped, sep = " "))
    print("Liftover completed")
    return(hg19_bed)
  }
  if(chain == "HG19TOHG18"){
    #make sure genome version is correct
    if(length(grep("hg19", bedfile)) == 0){
      bedfile_temp <- gsub(pattern = ".bed", replacement = "_hg19.bed", x = bedfile, ignore.case = T)
      print("Warning: genome version not specified, assuming hg19")
    }else{
      bedfile_temp <- bedfile
    }
    #input is a bedfile with "_hg19" in the name
    #note liftover will fail if start = end for a given region
    hg18_bed <- gsub(pattern = "_hg19", replacement = "_hg18", x = bedfile_temp, ignore.case = T)
    hg18_bed_unmapped <- gsub(pattern = "_hg19", replacement = "unmapped_to_hg18", x = bedfile_temp, ignore.case = T)
    #run the liftover
    system(paste("~/Desktop/Polymorphisms_Project/LiftOver/liftOver", bedfile, "~/Desktop/Polymorphisms_Project/LiftOver/Chains/hg19ToHg18.over.chain", hg18_bed, hg18_bed_unmapped, sep = " "))
    print("Liftover completed")
    return(hg18_bed)
  }
  if(chain == "HG19TOHG18"){
    #make sure genome version is correct
    if(length(grep("hg19", bedfile)) == 0){
      bedfile_temp <- gsub(pattern = ".bed", replacement = "_hg19.bed", x = bedfile, ignore.case = T)
      print("Warning: genome version not specified, assuming hg19")
    }else{
      bedfile_temp <- bedfile
    }
    #input is a bedfile with "_hg19" in the name
    #note liftover will fail if start = end for a given region
    hg18_bed <- gsub(pattern = "_hg19", replacement = "_hg18", x = bedfile_temp, ignore.case = T)
    hg18_bed_unmapped <- gsub(pattern = "_hg19", replacement = "unmapped_to_hg18", x = bedfile_temp, ignore.case = T)
    #run the liftover
    system(paste("~/Desktop/Polymorphisms_Project/LiftOver/liftOver", bedfile, "~/Desktop/Polymorphisms_Project/LiftOver/Chains/hg19ToHg18.over.chain", hg18_bed, hg18_bed_unmapped, sep = " "))
    print("Liftover completed")
    return(hg18_bed)
  }
  if(chain == "HG18TOHG38"){
    #make sure genome version is correct
    if(length(grep("hg18", bedfile)) == 0){
      bedfile_temp <- gsub(pattern = ".bed", replacement = "_hg18.bed", x = bedfile, ignore.case = T)
      print("Warning: genome version not specified, assuming hg18")
    }else{
      bedfile_temp <- bedfile
    }
    #input is a bedfile with "_hg19" in the name
    #note liftover will fail if start = end for a given region
    hg38_bed <- gsub(pattern = "_hg18", replacement = "_hg38", x = bedfile_temp, ignore.case = T)
    hg38_bed_unmapped <- gsub(pattern = "_hg18", replacement = "unmapped_to_hg38", x = bedfile_temp, ignore.case = T)
    #run the liftover
    system(paste("~/Desktop/Polymorphisms_Project/LiftOver/liftOver", bedfile, "~/Desktop/Polymorphisms_Project/LiftOver/Chains/hg18ToHg38.over.chain", hg38_bed, hg38_bed_unmapped, sep = " "))
    print("Liftover completed")
    return(hg38_bed)
  }
  if(chain == "MM10TOHG38"){
    #make sure genome version is correct
    if(length(grep("mm10", bedfile)) == 0){
      bedfile_temp <- gsub(pattern = ".bed", replacement = "_mm10.bed", x = bedfile, ignore.case = T)
      print("Warning: genome version not specified, assuming mm10")
    }else{
      bedfile_temp <- bedfile
    }
    #input is a bedfile with "_mm10" in the name
    #note liftover will fail if start = end for a given region
    hg38_bed <- gsub(pattern = "_mm10", replacement = "_hg38", x = bedfile_temp, ignore.case = T)
    hg38_bed_unmapped <- gsub(pattern = "_mm10", replacement = "unmapped_to_hg38", x = bedfile_temp, ignore.case = T)
    #run the liftover
    system(paste("~/Desktop/Polymorphisms_Project/LiftOver/liftOver -multiple -minMatch=0.1", bedfile, "~/Desktop/Polymorphisms_Project/LiftOver/Chains/mm10ToHg38.over.chain", hg38_bed, hg38_bed_unmapped, sep = " "))
    print("Liftover completed")
    return(hg38_bed)
  }
  if(chain == "CHM13TOHG38"){
    #make sure genome version is correct
    if(length(grep("Chm13", bedfile)) == 0){
      bedfile_temp <- gsub(pattern = ".bed", replacement = "_Chm13.bed", x = bedfile, ignore.case = T)
      print("Warning: genome version not specified, assuming Chm13, T2T")
    }else{
      bedfile_temp <- bedfile
    }
    #input is a bedfile with "_hg19" in the name
    #note liftover will fail if start = end for a given region
    hg38_bed <- gsub(pattern = "_Chm13", replacement = "_hg38", x = bedfile_temp, ignore.case = T)
    hg38_bed_unmapped <- gsub(pattern = "_Chm13", replacement = "unmapped_to_hg38", x = bedfile_temp, ignore.case = T)
    #run the liftover
    system(paste("~/Desktop/Polymorphisms_Project/LiftOver/liftOver", bedfile, "~/Desktop/Polymorphisms_Project/LiftOver/Chains/chm13v2-grch38.chain", hg38_bed, hg38_bed_unmapped, sep = " "))
    print("Liftover completed")
    return(hg38_bed)
  }
}

#create function to plot bed regions on human skeleton
plot_bed_overlaps_early <- function(bed_file, plot_name){
  #load custom functions for analysis
  source("~/Desktop/Capellini_Lab/Weekly_Coding/Skeleton_Heatmap_V1.R")
  
  results_df <- read.table("~/Desktop/Capellini_Lab/Weekly_Coding/skeleton_heatmap_beds.txt", header = T) %>%  dplyr::filter(!is.na(early_file))
  for(x in 1:nrow(results_df)){
    results_df$value[x] <- system(paste("cat ", bed_file, " | bedtools intersect -a stdin -b ", results_df$early_file[x], " | wc -l", sep =""), intern =T) %>% 
      readr::parse_number()
  } #end iterate over tissues
  
  
  plot_skeleton_heatmap(expr_df = results_df %>% dplyr::select(tissue, value), inc.autopods = T, file_name = paste("~/Desktop/Autopod_Skeleton_Figures/", plot_name, "_early_skeleton_heatmap", sep = ""), key_label = "Overlaps")
} #end plot_bed_regions function

