#create function to return number of genes in window around certain genes
window_expr_gene <- function(feature_bed, autopod_threshold = 0, threshold_type = "max", distance = 500000){
  require(data.table)
  require(tidyverse)
  #load required functions
  source("~/Desktop/Capellini_Lab/Weekly_Coding/Daniel_HAR_enrichment_functions.R")
  
  #load gene info 
  gene_bed <- "~/Desktop/Capellini_Lab/Capellini_Lab_Peak_Sets/Other_Peak_sets/hg38_refGene.sorted.bed"
  gene_df <- fread(file = gene_bed, sep = "\t", header = F)
  colnames(gene_df) <- c("chr", "start", "end", "gene")
  temp_gene_set <- "~/Desktop/TEMP_ATAC_DIR/temp_gene_set.bed"
  temp_feature_set <- "~/Desktop/TEMP_ATAC_DIR/temp_feature_set.bed"
  
  #load gene expression info
  max_gene_expr <- fread(file = "~/Desktop/Capellini_Lab/Human Autopod RNA/human_max_gene_expr.tsv", sep = "\t", header = T)
  colnames(max_gene_expr) <- c("gene", "max_expr", "min_expr")
  
  #reduce gene bed to expressed genes 
  if(toupper(threshold_type) == 'MAX'){
    gene_df_subset <- gene_df %>% 
      dplyr::filter(gene %in% max_gene_expr$gene[which(max_gene_expr$max_expr >= autopod_threshold)]) %>% 
      unique()
    write_bed(gene_df_subset, filename = temp_gene_set, ncol = 4)
  }
  if(toupper(threshold_type) == 'MIN'){
    gene_df_subset <- gene_df %>% 
      dplyr::filter(gene %in% max_gene_expr$gene[which(max_gene_expr$min_expr >= autopod_threshold)]) %>% 
      unique()
    write_bed(gene_df_subset, filename = temp_gene_set, ncol = 4)
    
  }
  
  #get counts 
  feature_table <- read.delim(feature_bed, sep = "\t", header = F)
  colnames(gene_table)[1:3] <- c("chr", "start", "end")
  system(paste("bedtools window -a ", feature_bed, " -b ", temp_gene_set, " -w ", distance," > ", temp_feature_set, sep = ""))
  temp_feature_df <- fread(file = temp_feature_set, sep = "\t", header = F) 
  temp_feature_df$distance <- 0
  temp_feature_df$distance[which(temp_feature_df$V5 > temp_feature_df$V3)] <- temp_feature_df$V5[which(temp_feature_df$V5 > temp_feature_df$V3)] - temp_feature_df$V3[which(temp_feature_df$V5 > temp_feature_df$V3)]
  temp_feature_df$distance[which(temp_feature_df$V2 > temp_feature_df$V6)] <- temp_feature_df$V2[which(temp_feature_df$V2 > temp_feature_df$V6)] - temp_feature_df$V6[which(temp_feature_df$V2 > temp_feature_df$V6)]
  colnames(temp_feature_df)[c(1:3, ncol(temp_feature_df)-1, ncol(temp_feature_df))] <- c("chr", "start", "end",  "gene", "distance")
  temp_feature_df_clean <- temp_feature_df %>% 
    group_by(chr, start, end,  gene) %>% 
    summarise(min_dist = round(min(distance))) %>% 
    unique() %>% 
    dplyr::left_join(max_gene_expr) %>% 
    dplyr::arrange(chr, start, -min_expr) 
  
  
  #cleanup
  system(paste("rm ", temp_gene_set, sep = ""))
  system(paste("rm ", temp_feature_set, sep = ""))
  
  
  return(as.data.frame(temp_feature_df_clean))
}

