##overlap with hCONDEL

hCONDEL_Profile <- function(bedfiles){
  #store results
  hCONDEL_data <- data.frame()
  #specify hCONDELs bedfile
  hCONDELs <- "/Users/alexanderokamoto/Desktop/Capellini_Lab/Capellini_Lab_Peak_Sets/Other_Peak_sets/hCONDELs_Xue_McLean_hg38.bed"
  #load hCONDEL deletions sizes
  hCONDEL_sizes <- read.delim(file = "/Users/alexanderokamoto/Desktop/Capellini_Lab/Capellini_Lab_Peak_Sets/Other_Peak_sets/hCONDEL_deletion_sizes.txt", header = T, sep = "\t")
  
  
  #iterate over bed files
  for (file in bedfiles){
    #overlap files and save to temporary bed
    system(paste("bedtools intersect -a", hCONDELs, "-b", file, "-wa > ~/Desktop/TEMP_ATAC_DIR/hCONDELS_OVERLAP_TEMP.bed", sep = " "))
    temp_hCONDEL_overlap <- read.delim(file = "~/Desktop/TEMP_ATAC_DIR/hCONDELS_OVERLAP_TEMP.bed", header = F, sep = "\t")
    names(temp_hCONDEL_overlap) <- c("chr", "start", "end", "hCONDEL_ID")
    temp_hCONDEL_overlap$file <- file
    hCONDEL_data <- rbind(hCONDEL_data, temp_hCONDEL_overlap)
    system("rm ~/Desktop/TEMP_ATAC_DIR/hCONDELS_OVERLAP_TEMP.bed")
  }
  hCONDEL_data <- merge(hCONDEL_data, hCONDEL_sizes)
  
  return(hCONDEL_data)
}

