#perform Gene Ontology (GO) enrichment
#requires:
#a universe of ensembl IDs for the background gene set
#a species database (either human or mouse presumable) to get gene information from
#a set of clustering results containing ensemble gene IDs in a "gene_id" column and cluster in a "cluster" column
#the name of the csv file to save the results to

simple_go_analysis <- function(gene_list, universe = "all", database = org.Hs.eg.db){
  require(clusterProfiler) #for gene enrichment
  require(org.Hs.eg.db)
  require(org.Mm.eg.db)
  refgene_bed <- "~/Desktop/Capellini_Lab/Capellini_Lab_Peak_Sets/Other_Peak_sets/hg38_refGene.sorted.bed"
  if(universe == "all"){
    gene_df <- fread(file = refgene_bed, sep = "\t", header = F)
    colnames(gene_df) <- c("chr", "start", "end", "gene")
    universe = gene_df$gene
  }
  
  
  GO_results <- enrichGO(gene = gene_list, 
                         universe = universe,
                         keyType = "SYMBOL",
                         OrgDb = database, 
                         ont = "BP", 
                         pAdjustMethod = "BH", 
                         qvalueCutoff = 0.05, 
                         readable = TRUE) %>% as.data.frame()
  
  return(GO_results)
  
  
} #end function

#given a peak, plot human autopod accessibility
#plots overlap at either timepoint

plot_autopod_peak <- function(chr, start, end, id = 'none'){
  #load dataframe to fill for plotting
  results_df <- read.table("~/Desktop/Capellini_Lab/Weekly_Coding/skeleton_heatmap_beds.txt", header = T)[1:20,]
  results_df$sampleType = c("FM1", "FM2", "FM3", "FM4", "FM5", "FP1", "FP2", "FP3", "FP4", "FP5", "HM1", "HM2", "HM3", "HM4", "HM5", "HP1", "HP2", "HP3", "HP4", "HP5")
  
  for(x in 1:nrow(results_df)){
    results_df$value_early[x] <- system(paste("echo '", chr, "\t", start, "\t", end, "' | bedtools intersect -a stdin -b ", results_df$early_file[x], " | wc -l", sep =""), intern =T) %>% 
      readr::parse_number()
    results_df$value_late[x] <- system(paste("echo '", chr, "\t", start, "\t", end, "' | bedtools intersect -a stdin -b ", results_df$late_file[x], " | wc -l", sep =""), intern =T) %>% 
      readr::parse_number()
  } #end iterate over tissues
  results_df$value <- pmax(results_df$value_early, results_df$value_late)
  #cleanup for plotting
  if(id == 'none'){
    id <- paste(chr, ":", start, "-", end, sep = "")
  }
  
  plot_autopod_expression(expr_df = results_df %>% mutate(tissue = sampleType) %>% dplyr::select(tissue, value), 
                          file_name = paste(id, "_autopod_accessibility_heatmap", sep = ""), 
                          opt_text = id)
} #end plot_bed_regions function


