#create a function to visualize accessibility of HARs/hCONDELS near a given gene
har_REs_near_gene <- function(target_gene, dist){
  #load and format dataset
  refgene_bed <- "~/Desktop/Capellini_Lab/Capellini_Lab_Peak_Sets/Other_Peak_sets/hg38_refGene.sorted.bed"
  gene_df <- fread(file = refgene_bed, sep = "\t", header = F)
  colnames(gene_df) <- c("chr", "start", "end", "gene")
  
  #HAR and hCONDEL list
  HARs_hCONDELs <- "/Users/alexanderokamoto/Desktop/Capellini_Lab/Capellini_Lab_Peak_Sets/Other_Peak_sets/HARs_hCONDELS_hg38.bed"
  
  #make temp files for use
  temp_target_gene_bed <- "~/Desktop/TEMP_ATAC_DIR/temp_target_gene.bed"
  temp_gene_overlaps_bed <- "~/Desktop/TEMP_ATAC_DIR/temp_gene_overlaps.bed"
  
  #subset gene list to target gene
  target_gene_df_subset <- gene_df %>% 
    dplyr::filter(gene == toupper(target_gene)) %>% 
    unique()
  
  #check if unique gene match found
  if(nrow(target_gene_df_subset) == 1){
    print("Gene coordinates found successfully.")
  }
  
  #write bed file containing just the target gene region
  write_bed(target_gene_df_subset, filename = temp_target_gene_bed, ncol = 4)
  pad_bed_orig(temp_target_gene_bed, padding = dist)
  padded_gene_bed <- paste("~/Desktop/TEMP_ATAC_DIR/temp_target_gene_padded", dist,".bed", sep = "")
  
  #this explicitly requires overlap with autopod regulatory element
  autopod_data <- "/Users/alexanderokamoto/Desktop/Capellini_Lab/Capellini_Lab_Peak_Sets/All_Capellini_Sets/human_all_merge_IDR_0.05_brain_filtered.bed"
  system(paste("bedtools intersect -a ", padded_gene_bed, " -b ", autopod_data, " | bedtools intersect -a ", HARs_hCONDELs, " -b stdin -wa | uniq > ", temp_gene_overlaps_bed, sep = ""))
  
  #load in overlap coordinates
  overlap_df <- fread(file = temp_gene_overlaps_bed, sep = "\t", header = F)
  colnames(overlap_df) <- c("chr", "start", "end", "id")
  
  #create a new directory to store results
  dir_name <- paste(target_gene, "_", dist, sep = "")
  try(system(paste("mkdir ~/Desktop/Autopod_Skeleton_Figures/", dir_name, sep = "")))
  
  #iterate over rows
  for (i in 1:nrow(overlap_df)){
    plot_autopod_peak(chr = overlap_df$chr[i], 
                      start = overlap_df$start[i], 
                      end = overlap_df$end[i], 
                      id = paste(dir_name, "/", 
                                 overlap_df$chr[i], "_", 
                                 overlap_df$start[i], "_",
                                 overlap_df$end[i], "_",
                                 overlap_df$id[i],
                                 sep = "")
    )
  }
  
  return(overlap_df)
  
  #cleanup 
  system(paste("rm", temp_target_gene_bed))
  system(paste("rm", temp_gene_overlaps_bed))
}

