#compare two DNA sequences and find the first SNP difference
#if the length of the sequences are not equal, return "999" to prevent R treating NA as a 0 for downstream steps
find_SNP <- function(x, y){
  count <- 0
  x_bps <- unlist(str_split(x, pattern = ""))
  y_bps <- unlist(str_split(y, pattern = ""))
  if(length(x_bps) == length(y_bps)){
    first_diff <- which(sapply(seq(length(x_bps)),
                               function(i){
                                 x_bps[i] != y_bps[i]
                               }))[1]
    return(c(x_bps[first_diff], y_bps[first_diff]))
  }else{
    return(999)
  }
}

